-- ==========================================================
-- Manjar · ventas de ejemplo para ver los reportes (SOLO DESARROLLO)
--
-- Qué hace: agrega a "Fonda Doña Lupe" dos semanas de ventas ya cobradas (comandas y apartados entregados) con
-- sus cajas cerradas, para que Reportes y Vista consolidada tengan qué mostrar desde el primer día.
-- Las ventas se fechan hacia atrás desde HOY (ayer, antier, etc.); el día de hoy queda libre para operar.
--
-- Antes de ejecutarlo: database/manjar.sql, database/migracion_personalizacion.sql,
-- database/migracion_operacion.sql y database/datos_prueba.sql (usa sus cuentas y platillos).
-- Se puede ejecutar de nuevo sin duplicar nada. Cada comanda de ejemplo lleva la mesa "DEMO-<día>-<n>".
-- Para quitarlas: DELETE de movimientocaja, detallecomanda y comanda con MESA LIKE 'DEMO-%'
-- (y de pago, detalleapartado, apartado con CODIGOCOMPROBANTE LIKE 'DEMO%'; y las cajas de esos días).
-- ==========================================================

USE manjar;
SET NAMES utf8mb4;

-- ---------- Día -14 ----------
INSERT INTO caja (ESTABLECIMIENTOID, USUARIOID, FECHAAPERTURA, MONTOINICIAL, ESTADO, FECHACIERRE, MONTOESPERADO, MONTOCONTADO, DIFERENCIA, CERRADAPORID)
SELECT (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe'), (SELECT ID FROM usuario WHERE Correo = 'gerente@manjar.test'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '08:00:00'), 500.00, 'CERRADA', TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '17:00:00'), 596.00, 596.00, 0.00, (SELECT ID FROM usuario WHERE Correo = 'gerente@manjar.test') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM caja WHERE ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe') AND FECHAAPERTURA = TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '08:00:00'));

INSERT INTO comanda (MESEROID, MESA, ESTADO, ESTABLECIMIENTOID, TIPO, FECHAHORA, FECHACOBRO)
SELECT (SELECT ID FROM usuario WHERE Correo = 'gerente@manjar.test'), 'DEMO-14-1', 'ENTREGADA', (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe'), 'MESA', TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '10:45:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '10:45:00') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM comanda WHERE MESA = 'DEMO-14-1' AND ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe'));
INSERT INTO detallecomanda (COMANDAID, PLATILLOID, CANTIDAD, PRECIOUNITARIO, COSTOUNITARIO)
SELECT c.ID, p.ID, 3, p.Precio, p.COSTO FROM comanda c JOIN platillo p ON p.ESTABLECIMIENTOID = c.ESTABLECIMIENTOID AND p.Nombre = 'Caldo de res'
WHERE c.MESA = 'DEMO-14-1' AND c.ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe')
AND NOT EXISTS (SELECT 1 FROM detallecomanda x WHERE x.COMANDAID = c.ID AND x.PLATILLOID = p.ID);
INSERT INTO detallecomanda (COMANDAID, PLATILLOID, CANTIDAD, PRECIOUNITARIO, COSTOUNITARIO)
SELECT c.ID, p.ID, 1, p.Precio, p.COSTO FROM comanda c JOIN platillo p ON p.ESTABLECIMIENTOID = c.ESTABLECIMIENTOID AND p.Nombre = 'Agua de horchata'
WHERE c.MESA = 'DEMO-14-1' AND c.ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe')
AND NOT EXISTS (SELECT 1 FROM detallecomanda x WHERE x.COMANDAID = c.ID AND x.PLATILLOID = p.ID);
INSERT INTO movimientocaja (CAJAID, COMANDAID, TIPO, MONTO, CONCEPTO, FECHAHORA, CLASE, METODO, USUARIOID)
SELECT (SELECT ID FROM caja WHERE ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe') AND FECHAAPERTURA = TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '08:00:00')), c.ID, 'INGRESO', 280.00, 'Cobro de comanda', TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 14 DAY), '10:45:00'), 'VENTA', 'TRANSFERENCIA', (SELECT ID FROM usuario WHERE Correo = 'gerente@manjar.test') FROM comanda c
WHERE c.MESA = 'DEMO-14-1' AND c.ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe')
AND NOT EXISTS (SELECT 1 FROM movimientocaja m WHERE m.COMANDAID = c.ID);

