SELECT (SELECT ID FROM usuario WHERE Correo = 'gerente@manjar.test'), 'DEMO-1-4', 'ENTREGADA', (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe'), 'MESA', TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 1 DAY), '13:05:00'), TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 1 DAY), '13:05:00') FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM comanda WHERE MESA = 'DEMO-1-4' AND ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe'));
INSERT INTO detallecomanda (COMANDAID, PLATILLOID, CANTIDAD, PRECIOUNITARIO, COSTOUNITARIO)
SELECT c.ID, p.ID, 1, p.Precio, p.COSTO FROM comanda c JOIN platillo p ON p.ESTABLECIMIENTOID = c.ESTABLECIMIENTOID AND p.Nombre = 'Caldo de res'
WHERE c.MESA = 'DEMO-1-4' AND c.ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe')
AND NOT EXISTS (SELECT 1 FROM detallecomanda x WHERE x.COMANDAID = c.ID AND x.PLATILLOID = p.ID);
INSERT INTO detallecomanda (COMANDAID, PLATILLOID, CANTIDAD, PRECIOUNITARIO, COSTOUNITARIO)
SELECT c.ID, p.ID, 3, p.Precio, p.COSTO FROM comanda c JOIN platillo p ON p.ESTABLECIMIENTOID = c.ESTABLECIMIENTOID AND p.Nombre = 'Agua de horchata'
WHERE c.MESA = 'DEMO-1-4' AND c.ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe')
AND NOT EXISTS (SELECT 1 FROM detallecomanda x WHERE x.COMANDAID = c.ID AND x.PLATILLOID = p.ID);
INSERT INTO movimientocaja (CAJAID, COMANDAID, TIPO, MONTO, CONCEPTO, FECHAHORA, CLASE, METODO, USUARIOID)
SELECT (SELECT ID FROM caja WHERE ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe') AND FECHAAPERTURA = TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 1 DAY), '08:00:00')), c.ID, 'INGRESO', 160.00, 'Cobro de comanda', TIMESTAMP(DATE_SUB(CURDATE(), INTERVAL 1 DAY), '13:05:00'), 'VENTA', 'EFECTIVO', (SELECT ID FROM usuario WHERE Correo = 'gerente@manjar.test') FROM comanda c
WHERE c.MESA = 'DEMO-1-4' AND c.ESTABLECIMIENTOID = (SELECT ID FROM establecimiento WHERE Nombre = 'Fonda Doña Lupe')
AND NOT EXISTS (SELECT 1 FROM movimientocaja m WHERE m.COMANDAID = c.ID);

SELECT COUNT(*) AS comandas_de_ejemplo FROM comanda WHERE MESA LIKE 'DEMO-%';
